CREATE TABLE "delivery_providers" ("id" UUID NOT NULL, "code" VARCHAR(40) NOT NULL, "name" VARCHAR(100) NOT NULL, "provider_type" VARCHAR(30) NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL, CONSTRAINT "delivery_providers_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "delivery_providers_code_key" ON "delivery_providers"("code");
CREATE TABLE "delivery_provider_configurations" ("id" UUID NOT NULL, "provider_id" UUID NOT NULL, "environment" VARCHAR(20) NOT NULL DEFAULT 'uat', "market" VARCHAR(8) NOT NULL DEFAULT 'PH', "show_at_checkout" BOOLEAN NOT NULL DEFAULT false, "automatic_selection_enabled" BOOLEAN NOT NULL DEFAULT false, "platform_markup" DECIMAL(12,2) NOT NULL DEFAULT 0, "maximum_customer_fee" DECIMAL(12,2), "available_for" JSONB NOT NULL DEFAULT '{}', "last_connection_status" VARCHAR(30) NOT NULL DEFAULT 'NOT_TESTED', "last_tested_at" TIMESTAMPTZ, "last_successful_api_at" TIMESTAMPTZ, "last_error" VARCHAR(300), "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL, CONSTRAINT "delivery_provider_configurations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "delivery_provider_configurations_provider_id_key" ON "delivery_provider_configurations"("provider_id");
CREATE TABLE "delivery_provider_credentials" ("id" UUID NOT NULL, "provider_id" UUID NOT NULL, "credential_key" VARCHAR(60) NOT NULL, "encrypted_value" TEXT NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL, CONSTRAINT "delivery_provider_credentials_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "delivery_provider_credentials_provider_id_credential_key_key" ON "delivery_provider_credentials"("provider_id", "credential_key");
CREATE TABLE "delivery_provider_audit_logs" ("id" UUID NOT NULL, "provider_id" UUID NOT NULL, "actor_id" UUID NOT NULL, "action" VARCHAR(80) NOT NULL, "changes" JSONB, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "delivery_provider_audit_logs_pkey" PRIMARY KEY ("id"));
CREATE INDEX "delivery_provider_audit_logs_provider_id_created_at_idx" ON "delivery_provider_audit_logs"("provider_id", "created_at");
ALTER TABLE "delivery_provider_configurations" ADD CONSTRAINT "delivery_provider_configurations_provider_id_fkey" FOREIGN KEY ("provider_id") REFERENCES "delivery_providers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "delivery_provider_credentials" ADD CONSTRAINT "delivery_provider_credentials_provider_id_fkey" FOREIGN KEY ("provider_id") REFERENCES "delivery_providers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "delivery_provider_audit_logs" ADD CONSTRAINT "delivery_provider_audit_logs_provider_id_fkey" FOREIGN KEY ("provider_id") REFERENCES "delivery_providers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
